def apply_lease_tax(quote: dict, tax_rate_bps: int) -> dict:
    net = int(quote['net_cents'])
    tax = (net * int(tax_rate_bps)) // 10000
    return {
        'net_cents': net,
        'tax_cents': tax,
        'gross_cents': net + tax,
        'tax_lease_window': [0, 3],
        'tax_fencing_token': 1,
    }

